from collections import deque

def find_connected_components(grid, start_r, start_c, exclude_color=5):
    """Find all cells connected to start position with same color."""
    color = grid[start_r][start_c]
    if color == exclude_color:
        return []

    rows, cols = len(grid), len(grid[0])
    visited = set()
    component = []
    queue = deque([(start_r, start_c)])

    while queue:
        r, c = queue.popleft()
        if (r, c) in visited:
            continue
        visited.add((r, c))
        component.append((r, c))

        for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nr, nc = r + dr, c + dc
            if 0 <= nr < rows and 0 <= nc < cols:
                if (nr, nc) not in visited and grid[nr][nc] == color and grid[nr][nc] != exclude_color:
                    queue.append((nr, nc))

    return component, color

# Find all connected components
all_components = {}
for r in range(len(grid)):
    for c in range(len(grid[0])):
        if grid[r][c] != 5 and grid[r][c] not in all_components:
            comp, color = find_connected_components(grid, r, c, exclude_color=5)
            all_components.setdefault(color, []).append(comp)

for color, comps in sorted(all_components.items()):
